def longest_unique(s: str) -> int:
    last_seen: dict[str, int] = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last_seen:
            start = max(start, last_seen[ch] + 1)
        last_seen[ch] = i
        best = max(best, i - start + 1)
    return best


s = input().strip()
print(longest_unique(s))

