#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>

int longestUnique(const std::string& s) {
    std::unordered_map<char, int> lastSeen;
    int start = 0;
    int best = 0;
    for (int i = 0; i < static_cast<int>(s.size()); i++) {
        auto it = lastSeen.find(s[i]);
        if (it != lastSeen.end()) {
            start = std::max(start, it->second + 1);
        }
        lastSeen[s[i]] = i;
        best = std::max(best, i - start + 1);
    }
    return best;
}

int main() {
    std::string s;
    std::cin >> s;
    std::cout << longestUnique(s) << "\n";
    return 0;
}

