package main

import "fmt"

func longestUnique(s string) int {
	lastSeen := make(map[byte]int)
	start, best := 0, 0
	for i := 0; i < len(s); i++ {
		if j, ok := lastSeen[s[i]]; ok && j+1 > start {
			start = j + 1
		}
		lastSeen[s[i]] = i
		if i-start+1 > best {
			best = i - start + 1
		}
	}
	return best
}

func main() {
	var s string
	fmt.Scan(&s)
	fmt.Println(longestUnique(s))
}

